def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)

    # Find nearly uniform rectangles; these represent solid objects with
    # occasional pixels corrupted by noise.
    best = [[(0.0, bg) for _ in range(w)] for _ in range(h)]
    for color in counts:
        if color == bg:
            continue
        for r0 in range(h):
            for r1 in range(r0 + 1, min(h, r0 + 12)):
                height = r1 - r0 + 1
                for c0 in range(w):
                    for c1 in range(c0 + 1, min(w, c0 + 12)):
                        width = c1 - c0 + 1
                        area = height * width
                        if area < 4:
                            continue
                        n = sum(grid[r][c] == color
                                for r in range(r0, r1 + 1)
                                for c in range(c0, c1 + 1))
                        if n < 3 or n / area < 0.75:
                            continue
                        score = area * (n / area)
                        for r in range(r0, r1 + 1):
                            for c in range(c0, c1 + 1):
                                if score > best[r][c][0]:
                                    best[r][c] = (score, color)

    return [[best[r][c][1] for c in range(w)] for r in range(h)]
